            score -= 740.0 + (if slack == 0 { 620.0 } else if slack > 22 { 210.0 } else { -150.0 });
        } else {
            // Penalize stranding next item, scaling penalty by current bin count to discourage fragmentation.
            score += 750.0 + (progress * 520.0) + (open_bins_count as f64 * 5.2);
        }
    }

    // 3. Fragmentation Barrier: Target "dead zones" (1-28) with steeper cost curve.
    if post_residual > 0 && post_residual < 29 {
        score += 540.0 + (29.0 - post_residual as f64).powf(1.2) * 28.0;
    }

    // 4. Adaptive New Bin Control: Balancing density vs. opportunity cost.
    if is_new_bin {
        let density_factor = (open_bins_count as f64 / (step_index as f64 / 15.0 + 1.0)).sqrt();
        // Shift weight toward conservation in the final 20% of the stream.
        let late_game_multiplier = if progress > 0.8 { 2.2 } else { 1.0 };
        score += (1100.0 + (mean_residual * 3.8) + (progress.powi(2) * 1600.0) + (density_factor * 400.0)) * late_game_multiplier;
    } else {
        // 5. Residual Balancing: Penalize divergence from mean_residual to prevent "Swiss cheese" bins.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        if residual_diff > (bin_capacity as f64 * 0.10) {
            score += 380.0 + (residual_diff * 1.5);
        }
        // Early-game: preserve capacity for larger items by discouraging extremely tight packing.
        if post_residual < 14 && progress < 0.40 {
            score += 420.0 * (1.1 - progress * 2.5);
        }
    }

