    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Refined Tight-Fit Reward: Heavily incentivize perfect fits.
    if post_residual == 0 {
        score -= 1050.0;
    } else if post_residual < 6 {
        score -= 680.0 - (post_residual as f64 * 55.0);
    }

    // 2. Adaptive Lookahead: Fine-tuned pairing logic.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Reward precise pairing for the next item; penalize excessive slack.
            score -= 620.0 + (if slack == 0 { 480.0 } else if slack < 4 { 240.0 } else { -slack as f64 * 12.0 });
        } else {
            // Penalty for stranding, scaled by current open bins to prevent unnecessary fragmentation.
            score += 590.0 + (open_bins_count as f64 * 8.0);
        }
    }

    // 3. Fragmentation Penalty: Adaptive barrier against "dead zones" (3-32).
    // Penalize residuals that are too small to accommodate common item sizes (1-32 range).
    if post_residual > 2 && post_residual < 34 {
        score += 380.0 + (34.0 - post_residual as f64) * 22.0;
    }

    // 4. Adaptive New Bin Control: Non-linear cost scaling.
    if is_new_bin {
        // Dynamic barrier: discourage new bins more strongly as the stream reaches completion.
        let density_factor = (open_bins_count as f64 / ((step_index as f64 / 12.0) + 1.0)).sqrt();
        score += 920.0 + (mean_residual * 3.2) + (progress.powi(3) * 1250.0) + (density_factor * 320.0);
    } else {
        // 5. Residual Balancing: Penalize extreme deviations from mean.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        if residual_diff > (bin_capacity as f64 * 0.15) {
            score += 290.0;
        }
        // Early-game: Defer tight packing to preserve flexibility for large items.
        if post_residual < 10 && progress < 0.12 {
            score += 310.0;
        }
    }

    // 6. Necessity Override: Force selection of existing bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 3500.0;
    } else if fitting_bins_count == 0 && !is_new_bin {
        score += 9800.0;
    } else if fitting_bins_count > 2 && post_residual < 18 {
        // Prefer bins that are already "well-packed" if multiple fits are available to improve density.
        score -= 420.0;
    }

    score
}

