    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Refined Tight-Fit Reward: Optimized for higher packing density.
    if post_residual == 0 {
        score -= 1020.0;
    } else if post_residual < 10 {
        score -= 680.0 - (post_residual as f64 * 48.0);
    }

    // 2. Adaptive Lookahead: Predictively minimize wasted slack.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Reward pairing that leaves enough room for a secondary item (likely ~25)
            score -= 610.0 + (if slack == 0 { 480.0 } else if slack < 15 { 240.0 - (slack as f64 * 16.0) } else { 0.0 });
        } else {
            score += 580.0 + (open_bins_count as f64 * 6.5);
        }
    }

    // 3. Fragmentation Penalty: Adaptive barrier against dead zones.
    // Tightened to prevent creating small, unusable gaps.
    if post_residual > 0 && post_residual < 28 {
        score += 380.0 + (28.0 - post_residual as f64) * 22.0;
    }

    // 4. Adaptive New Bin Control: Non-linear cost scaling.
    if is_new_bin {
        // Force compaction by increasing new-bin cost as the stream progresses.
        let density_factor = (open_bins_count as f64 / (step_index as f64 / 20.0 + 1.0)).sqrt();
        score += 940.0 + (mean_residual * 3.2) + (progress.powi(2) * 1350.0) + (density_factor * 310.0);
    } else {
        // 5. Residual Balancing: Prevent local optima by smoothing distribution.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        if residual_diff > (bin_capacity as f64 * 0.15) {
            score += 280.0;
        }
        // Early-game: preserve capacity for larger items.
        if post_residual < 22 && progress < 0.3 {
            score += 290.0;
        }
    }

    // 6. Necessity Override: Force selection of existing bins to maximize utilization.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 3200.0;
    } else if fitting_bins_count == 0 && !is_new_bin {
        score += 9800.0;
    } else if fitting_bins_count > 2 && post_residual < 18 {
        // Consolidate bins with low residuals to keep high-capacity bins available.
        score -= 420.0;
    }

    score
}

