    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Base score is the post-placement residual (Best Fit principle).
    // We want to minimize this to fill bins tightly.
    let mut score = post;

    // Penalty for leaving "dead space": if the post_residual is too small to fit 
    // any likely future item (e.g., < 10), it becomes a liability.
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: If next_item_size exists, penalize bins that cannot fit it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding for opening new bins: 
    // As the stream progresses, we become more conservative about opening new bins.
    // If this is a new bin (res == cap), apply a progress-dependent cost.
    if res == cap {
        // Higher progress means we should prioritize existing bins over opening new ones.
        score += 35.0 + (30.0 * progress);
    }

    // Coupling with mean_residual: Reward bins that help bring the average 
    // residual closer to a target "tight" state (e.g., 15).
    let deviation = (mean_residual - 15.0).abs();
    score += deviation * 0.5;

    // Favor bins that are "last chance" (fitting_bins_count == 1) to avoid 
    // wasting space in other bins if this one is already partially filled.
    if fitting_bins_count == 1 && res < cap {
        score -= 5.0;
    }

    score
}

