    let mut score = post_residual as f64;

    // Penalty for leaving "unusable" small gaps (1-9) which are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Best-Fit logic: prioritize bins that leave the smallest post_residual
    // We apply a non-linear weight to the residual to favor tighter packing
    score += (post_residual as f64).powf(1.2);

    // Lookahead logic: if next_item_size fits in the post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
