    // Harmonic/Modulo logic: prioritize leaving space that is a multiple of common item sizes
    // This creates "bins of specific sizes" rather than random fragments
    let harmonic_penalty = (post_residual % 20) as f64;
    score += harmonic_penalty;

    // If this is the only bin that fits the current item, heavily favor it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New bin penalty: Only open a new bin if the best existing fit is extremely poor
    if bin_residual == bin_capacity {
        // Only consider new bin if we have many open bins already or if the average residual is very low
        score += 80.0 + (open_bins_count as f64 * 0.5);
    }

    // Progression scaling: As the stream nears the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

