pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1..9), it is highly likely to be wasted.
    // We penalize this heavily because items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the remaining space, 
    // we reward this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs();
        if diff == 0 {
            score -= 40.0; // Perfect fit reward
        } else if diff < 5 {
            score -= 20.0; // Near-perfect fit reward
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If there are other bins that could fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tightness bias: Favor bins where the post_residual is small (but >= 10) 
    // to keep the overall mean_residual low.
    if post_residual >= 10 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 5. Progression scaling: As we approach the end of the stream, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Harmonic/Exact Fit Reward: Prioritize closing bins perfectly or near-perfectly.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 12 {
        // High penalty for slivers, but reward small residuals if they allow a future fit.
        score += (12.0 - post_residual as f64) * 85.0;
    }

    // 2. Predictive Lookahead: Favor bins that leave room for the next item or minimize stranding.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item.
            score -= 650.0 + (if post_residual == next_item_size { 400.0 } else { 150.0 });
        } else if fitting_bins_count > 0 {
            // Penalize leaving this bin empty/poorly-fit if other bins exist.
            score += 450.0 + (open_bins_count as f64 * 4.0);
        }
    }

    // 3. Fragmentation Barrier: Penalize residuals that are too small to be useful.
    if post_residual > 0 && post_residual < 25 {
        score += 380.0 - (post_residual as f64 * 8.0);
    }

    // 4. Dynamic New Bin Control: Non-linear cost scaling based on global load.
    if is_new_bin {
        // Late-game: discourage new bins heavily to force compaction.
        // Early-game: allow new bins to maintain high mean_residual flexibility.
        let late_game_penalty = progress * 1400.0;
        let density_resistance = (open_bins_count as f64 * 12.0) / (mean_residual + 1.0);
        score += 950.0 + late_game_penalty + density_resistance;
    } else {
        // 5. Residual Balancing: Prevent local optima by penalizing extreme deviations.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        if residual_diff > (bin_capacity as f64 * 0.25) {
