            // Consolidate space in bins that have many competitors.
            score -= 400.0;
        }
    }

    // 7. Global Efficiency Bias: Penalize empty space more as the stream progresses.
    score += (progress * 150.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

