    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Precise Fit and Sliver Mitigation
    // Perfect fits are prioritized. Small slivers are heavily penalized unless they are zero.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 12 {
        score += 450.0 - (post_residual as f64 * 35.0);
    }

    // 2. Dynamic Lookahead Synergy
    // Heavily incentivize placing the current item in a bin that leaves space for the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Reward exact matches for next_item_size and penalize mid-range slack (12-25)
            score -= 750.0;
            if slack == 0 { score -= 500.0; }
            else if slack < 25 { score += (25 - slack) as f64 * 12.0; }
        } else {
            // Penalty for forcing an item into a bin that cannot accommodate the upcoming item.
            score += 650.0 + (open_bins_count as f64 * 3.5);
        }
    }

    // 3. Fragmentation Barrier
    // Penalize residuals that fall in "dead zones" where few common item sizes fit.
    if post_residual > 12 && post_residual < 38 {
        score += 280.0 + (38.0 - post_residual as f64) * 15.0;
    }

    // 4. Adaptive New Bin Control
    // Non-linear cost scaling to force compaction in the final stages of the stream.
    if is_new_bin {
        let late_game_penalty = progress.powf(2.0) * 1600.0;
        let density_resistance = (open_bins_count as f64 / (1.0 + mean_residual)).sqrt() * 400.0;
        score += 1100.0 + late_game_penalty + density_resistance;
    } else {
        // Encourage balanced residual distribution across open bins.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        if residual_diff > (bin_capacity as f64 * 0.25) {
            score += 180.0;
        }
    }

    // 5. Necessity and Consolidation
    // Force usage of the last fitting bin to prevent "dangling" items.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 3200.0;
    } else if fitting_bins_count == 0 && !is_new_bin {
        score += 10000.0;
    } else if fitting_bins_count > 2 && post_residual < 20 {
        // Consolidate smaller items into bins that are already well-utilized.
        score -= 450.0;
    }

    // 6. Harmonic Smoothing
    // Mild reward for aligning with common item size increments (20, 25).
    score += (post_residual % 20) as f64 * 0.8;

    score
}

