    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;
    let bin_utilization = 1.0 - (bin_residual as f64 / bin_capacity as f64);

    // 1. Refined Tight-Fit Reward: Prioritize exact matches and near-perfect fills.
    if post_residual == 0 {
        score -= 1350.0;
    } else if post_residual < 8 {
        score -= 920.0 - (post_residual as f64 * 72.0);
    }

    // 2. Predictive Lookahead: Dynamically weight next_item_size fitting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Reward pairings that leave either 0 or a large enough space for future items.
            score -= 750.0 + (if slack == 0 { 620.0 } else if slack > 15 { 210.0 } else { -150.0 });
        } else {
            // Penalize stranding next item, increase penalty relative to remaining stream progress.
            score += 820.0 + (progress * 580.0) + (open_bins_count as f64 * 4.2);
        }
    }

    // 3. Fragmentation Barrier: Target "dead zones" (1-20) more aggressively.
    if post_residual > 0 && post_residual < 21 {
        score += 550.0 + (21.0 - post_residual as f64) * 28.0;
    }

    // 4. Adaptive New Bin Control: Non-linear cost scaling.
    if is_new_bin {
        // Late-game: discourage new bins; early-game: favor new bins to maximize bin spread.
        let density_factor = (open_bins_count as f64 / (step_index as f64 / 25.0 + 1.0)).sqrt();
        score += 1150.0 + (mean_residual * 4.5) + (progress.powi(2) * 1800.0) + (density_factor * 410.0);
    } else {
        // 5. Residual Balancing: Prevent variance in fill levels across open bins.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        if residual_diff > (bin_capacity as f64 * 0.15) {
            score += 420.0 + (residual_diff * 1.2);
        }
        // Early-game: discourage tight packing to preserve bins for large spikes.
        if post_residual < 15 && progress < 0.4 {
            score += 450.0 * (1.0 - progress * 2.5);
        }
    }

    // 6. Necessity Logic: Override heuristic for forced fits or bin consolidation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 4500.0;
    } else if fitting_bins_count == 0 && !is_new_bin {
        score += 15000.0;
    } else if fitting_bins_count > 2 && post_residual < 12 {
        // Consolidate space in bins that are already partially filled.
        score -= 650.0 * bin_utilization;
    }

    score
}

