    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual).
    // We add a penalty for "near-misses" (very small post_residual that leaves unusable space).
    let mut score = post_res + (100.0 / (post_res + 1.0));

    // Non-linear coupling: As the stream progresses, prioritize closing bins
    // by penalizing empty space more heavily when few items remain.
    let exhaustion_factor = 1.0 - progress;
    score += post_res * exhaustion_factor * 0.5;

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), add a significant cost
    // that decays as the stream progresses (making it easier to open bins late-game).
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress * 0.5);
    }

    // Fitting density: If this is the only bin that can fit the item, 
    // reduce the score to ensure we don't accidentally open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize bins that deviate significantly from the mean residual
    // to encourage uniform fill levels across all open bins.
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Refined Tight-Fit Reward: Focus on minimizing terminal fragmentation.
    if post_residual == 0 {
        score -= 1420.0;
    } else if post_residual < 6 {
        score -= 1150.0 - (post_residual as f64 * 120.0);
    }

    // 2. Predictive Lookahead: Enhanced coupling to prevent "bin-locking" small items.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Reward pairings that leave either zero residual or room for a mid-sized item (>= 32).
            score -= 880.0 + (if slack == 0 { 720.0 } else if slack > 32 { 350.0 } else if slack < 8 { -200.0 } else { 100.0 });
        } else {
            // Aggressive penalty for stranding, scaled by the ratio of bins to items (density pressure).
            score += 920.0 + (progress * 680.0) + (open_bins_count as f64 * 8.4);
        }
    }

    // 3. Fragmentation Barrier: Target "dead zones" (1-32) with a non-linear gravity well.
    if post_residual > 0 && post_residual < 33 {
        score += 680.0 + (33.0 - post_residual as f64).powf(1.4) * 32.0;
    }

    // 4. Adaptive New Bin Control: Dynamic sensitivity to current bin saturation.
    if is_new_bin {
        let density_factor = (open_bins_count as f64 / (step_index as f64 / 20.0 + 1.0)).sqrt();
        let late_game_multiplier = if progress > 0.85 { 2.8 } else { 1.0 };
        // Increase penalty for opening new bins when mean_residual suggests we have capacity.
        score += (1350.0 + (mean_residual * 4.2) + (progress.powi(2) * 2100.0) + (density_factor * 550.0)) * late_game_multiplier;
    } else {
        // 5. Residual Balancing: Penalize divergence from mean_residual to prevent "Swiss cheese" bins.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        if residual_diff > (bin_capacity as f64 * 0.12) {
            score += 450.0 + (residual_diff * 1.8);
        }
        // Early-game: preserve capacity for larger items by discouraging "early-fill" of high-potential bins.
        if post_residual < 18 && progress < 0.35 {
            score += 550.0 * (1.2 - progress * 2.8);
        }
    }

    // 6. Necessity Logic: Strict consolidation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 4200.0;
    } else if fitting_bins_count == 0 && !is_new_bin {
        score += 18000.0;
    } else if fitting_bins_count > 2 && post_residual < 16 {
        // Consolidate space in bins that are already well-utilized.
        score -= 720.0;
    }

    score
}

