    // If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // Scale penalty based on the number of already open bins to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 2.0);
    }

    // Adjust for global state: if mean_residual is high, we are already fragmenting too much.
    // Penalize bins that create post_residuals significantly smaller than the current mean.
    if (post_residual as f64) < mean_residual {
        score += 5.0;
    }

    // Progress-based scaling: towards the end of the stream, be more conservative 
    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Enhanced Tight-Fit Reward: Prioritize exact closure to minimize fragmentation.
    if post_residual == 0 {
        score -= 5200.0;
    } else if post_residual < 10 {
        score -= 3800.0 - (post_residual as f64 * 300.0);
    }

    // 2. Predictive Lookahead: Coupling next_item_size with residual geometry.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Reward "Goldilocks" slack: prioritize fitting next_item_size while keeping enough headroom
            score -= 3200.0 + (if slack == 0 { 2800.0 } else if slack > 14 { 800.0 } else { -200.0 });
        } else {
            // Penalize stranding next item based on global bin pressure and stream phase.
            score += 4200.0 + (progress * 3200.0) + (open_bins_count as f64 * 120.0);
        }
    }

    // 3. Fragmentation Barrier: Target "dead zones" (1-48) with adjusted non-linear weight.
    if post_residual > 0 && post_residual < 48 {
        let fragment_penalty = (48.0 - post_residual as f64).powf(2.4) * 110.0;
        score += 3000.0 + fragment_penalty;
    }

    // 4. Adaptive New Bin Control: Dynamically shift strategy based on stream exhaustion.
    if is_new_bin {
        let density_factor = (open_bins_count as f64 / (step_index as f64 / 60.0 + 1.0)).sqrt();
        // Aggressive late-game penalty to force usage of existing bins, tuned for higher efficiency.
        let late_penalty = if progress > 0.82 { 28.0 } else { 8.0 };
        score += (4200.0 + (mean_residual * 35.0) + (progress.powi(3) * 11000.0) + (density_factor * 3200.0)) * late_penalty;
    } else {
        // 5. Residual Balancing: Penalize divergence from mean_residual to homogenize bins.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        if residual_diff > (bin_capacity as f64 * 0.30) {
            score += 3000.0 + (residual_diff * 22.0);
        }
        // Early-game: preserve capacity for larger items.
        if post_residual < 35 && progress < 0.45 {
            score += 3200.0 * (1.8 - progress * 4.5);
        }
    }

    // 6. Necessity Logic: Forced consolidation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 28000.0;
    } else if fitting_bins_count == 0 && !is_new_bin {
        score += 200000.0;
    } else if fitting_bins_count > 2 && post_residual < 45 {
        // Encourage consolidation when multiple options exist, favoring tighter fits.
        score -= 7500.0 + (45.0 - post_residual as f64) * 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals < 10 are generally unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive Lookahead Matching: 
    // Reward bins where the post_residual is close to the next_item_size.
    // We prioritize bins that can perfectly accommodate the next expected item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // If the post_residual is exactly the next item size, apply a massive bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // 3. Global Efficiency Balancing:
    // If we have many bins open, penalize the creation of a new bin (bin_residual == bin_capacity)
    // proportional to the current mean_residual.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (mean_residual * 1.5) + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Pressure:
    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bin allocation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // 5. Progression Scaling:
    // As the stream nears completion, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
