            // Reward pairings that leave "buffer-safe" remainders (>22) or exact fits.
            score -= 820.0 + (if slack == 0 { 750.0 } else if slack > 24 { 240.0 } else { -180.0 });
        } else {
            // Penalize stranding next item, scaling penalty by progress to force consolidation.
            score += 880.0 + (progress * 640.0) + (open_bins_count as f64 * 6.8);
        }
    }

    // 3. Fragmentation Barrier: Target "dead zones" (1-24) with non-linear penalty curve.
    if post_residual > 0 && post_residual < 25 {
