        let density_factor = (open_bins_count as f64 / (step_index as f64 / 25.0 + 1.0)).sqrt();
        let late_game_multiplier = if progress > 0.85 { 2.8 } else { 1.2 };
        score += (1350.0 + (mean_residual * 4.2) + (progress.powi(2) * 1900.0) + (density_factor * 350.0)) * late_game_multiplier;
    } else {
        // 5. Residual Balancing: Penalize divergence from mean_residual to minimize variance.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        if residual_diff > (bin_capacity as f64 * 0.08) {
